// Split long replies into parts of at most 1900 characters (Discord's limit is 2000)
// so Discord never rejects a message with "Invalid Form Body".
const MAX_LEN = 1900;
const output = [];

for (const item of $input.all()) {
  let text = item.json.output || '';

  // Fallback when the agent returned nothing
  if (!text || text.trim() === '') {
    text = 'Duh, HUMI lagi nge-blank bentar nih kak 😅 Boleh diulang pertanyaannya?';
  }

  if (text.length <= MAX_LEN) {
    output.push({ json: { ...item.json, output: text, part: 1, totalParts: 1 } });
    continue;
  }

  // Split on line breaks first so a product block is not cut in the middle
  const chunks = [];
  let current = '';
  for (const line of text.split('\n')) {
    if ((current + '\n' + line).length > MAX_LEN) {
      if (current) chunks.push(current.trim());
      current = line;
    } else {
      current = current ? current + '\n' + line : line;
    }
  }
  if (current) chunks.push(current.trim());

  // A single line longer than MAX_LEN (rare) is cut by character count
  const finalChunks = [];
  for (const chunk of chunks) {
    if (chunk.length <= MAX_LEN) {
      finalChunks.push(chunk);
    } else {
      for (let i = 0; i < chunk.length; i += MAX_LEN) {
        finalChunks.push(chunk.slice(i, i + MAX_LEN));
      }
    }
  }

  finalChunks.forEach((chunk, idx) => {
    output.push({ json: { ...item.json, output: chunk, part: idx + 1, totalParts: finalChunks.length } });
  });
}

return output;

// The agent flags a hand-off with [[ESCALATE|category|summary]] at the end of its reply.
// Strip the marker from the customer's text and keep its content for the admin notification.
const MARKER = /\[\[ESCALATE\|([^|\]]*)\|([^\]]*)\]\]/g;

return $input.all().map((item) => {
  const text = item.json.output || '';
  const found = [...text.matchAll(MARKER)];
  const output = text.replace(MARKER, '').trim();
  if (found.length === 0) {
    return { json: { ...item.json, output, escalate: false } };
  }
  const [, category, summary] = found[found.length - 1];
  return { json: { ...item.json, output, escalate: true, category: category.trim(), summary: summary.trim() } };
});

// Summary for admins in #admin-hmns, with a direct link to the customer's message.
const b = $('Webhook - Discord In').first().json.body;
const label = {
  order: '📦 Pesanan',
  complaint: '😟 Komplain',
  human_request: '🙋 Minta admin',
  partnership: '🤝 Kerja sama',
  other: '📌 Lainnya',
}[$json.category] || `📌 ${$json.category || 'Lainnya'}`;
const quoted = (b.content || '').slice(0, 500).split('\n').map((line) => `> ${line}`).join('\n');
const link = b.guild_id
  ? `🔗 https://discord.com/channels/${b.guild_id}/${b.channel_id}/${b.message_id}`
  : '_Chat ini lewat DM ke HUMI. Hubungi customer lewat DM atau minta mampir ke #tanya-humi._';

const escalation_text = [
  `🚨 **Eskalasi dari HUMI** · ${label}`,
  `**Customer:** ${b.author_display_name || b.author_username} (@${b.author_username})`,
  `**Tempat:** ${b.is_dm ? 'DM ke HUMI' : '#' + b.channel_name}`,
  `**Ringkasan:** ${$json.summary || '-'}`,
  '**Pesan terakhir:**',
  quoted,
  link,
  '',
  'Tolong follow up langsung ke customer ya 🙏',
].join('\n');

return [{ json: { escalation_text } }];

// The agent failed (usually Groq's free per-minute token limit on both models). Reply politely instead of
// leaving the customer hanging, and alert admins at most once per hour. Customer and admin texts are in Indonesian.
const err = $json.error;
const message = typeof err === 'string' ? err : (err && (err.message || err.description)) || JSON.stringify(err || $json);
const details = String(message).toLowerCase();
const limited = ['429', 'quota', 'rate limit', 'too many requests'].some((k) => details.includes(k));

const state = $getWorkflowStaticData('global');
const now = Date.now();
const alert_admin = !state.lastAiAlertAt || now - state.lastAiAlertAt > 60 * 60 * 1000;
if (alert_admin) state.lastAiAlertAt = now;

const output = limited
  ? 'Waduh, HUMI lagi rame banget nih kak 🙏 Coba kirim lagi sekitar 1 menit lagi ya. Sambil nunggu, katalog lengkapnya bisa dicek di https://madeforhmns.com/collections/hmns ✨'
  : 'Duh, HUMI lagi ada gangguan teknis nih kak 🙏 Coba tanya lagi sebentar lagi ya.';
const admin_alert_text = limited
  ? '⚠️ **Batas gratis AI (Groq) tercapai.** Kedua model kena limit token per menit/hari, jadi customer sementara dapat pesan maaf otomatis. Limit per menit pulih dalam ±1 menit, limit harian reset tiap hari.'
  : `⚠️ **HUMI gagal menjawab customer.** Error: ${String(message).slice(0, 300)}`;

return [{ json: { output, alert_admin, admin_alert_text } }];
